import{_ as a,o as r,c as e,ag as s}from"./chunks/framework.CtWPcAmt.js";const c=JSON.parse('{"title":"第 15 章：Harness 是什么","description":"从「一个模型」转向「一个工作系统」；Agent、上下文、工具、权限、状态、验证、反馈回路七要素；用一次实测观察 Harness 运行。","frontmatter":{"title":"第 15 章：Harness 是什么","description":"从「一个模型」转向「一个工作系统」；Agent、上下文、工具、权限、状态、验证、反馈回路七要素；用一次实测观察 Harness 运行。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/15-what-is-harness.md","filePath":"guide/15-what-is-harness.md","lastUpdated":null}'),n={name:"guide/15-what-is-harness.md"};function l(d,t,i,o,h,g){return r(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="第-15-章-harness-是什么" tabindex="-1">第 15 章：Harness 是什么 <a class="header-anchor" href="#第-15-章-harness-是什么" aria-label="Permalink to &quot;第 15 章：Harness 是什么&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>到第四篇为止，你有了任务卡、模板、Skill、规则——一个个「零件」。本章把这些零件组装起来看：<strong>Agent 真正的工作系统（Harness）长什么样</strong>。你将理解：为什么同样的模型，在不同产品里表现不同；为什么「模型很强」不等于「结果可靠」。产出：<strong>个人 Harness 草图</strong>。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>第 5 章实测里，两款产品用了<strong>同一个模型</strong>（DeepSeek V4 Flash，都通过 OpenCode Go），但表现明显不同：</p><ul><li>ZCode 的审查视图把每份文件的增删行数列得清清楚楚（+46、+37、+84），变更透明性最强；</li><li>Hermes 把文件写错了目录，但自动发现、自动恢复、自动复核——恢复能力唯一实证。</li></ul><p><strong>模型一样，系统不同。</strong> 让它们产生差异的，不是「大脑」，而是「工作台」：工具怎么组织、权限怎么控制、状态怎么记录、验证怎么做——这套「工作台」就是 Harness。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>Harness 定义</strong>：把 Agent、上下文、工具、权限、状态、验证、反馈组织成一个工作系统的整体。白话解释：给 AI 配的「工作岗位 + 流程 + 规矩」，而不只是一个聊天框；</li><li><strong>从「一个模型」到「一个工作系统」</strong>：单用模型像请了个聪明人但没给办公桌；Harness 是给聪明人配齐办公桌、流程、门禁和质检；</li><li><strong>七要素各司其职</strong>：Agent（执行者）、上下文（视野）、工具（手脚）、权限（门禁）、状态（进度）、验证（质检）、反馈（复盘）；</li><li><strong>Harness 决定三件事</strong>：可靠性（稳不稳）、成本（贵不贵）、体验（顺不顺）——比模型选择影响更大；</li><li><strong>你已经在用 Harness 了</strong>：第 1–14 章攒的零件（任务卡、权限卡、CONTEXT、模板、Skill、规则）组装起来，就是你的个人 Harness——本章只是把它「显影」出来。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>Harness</strong>：围绕模型搭建的工作系统。白话解释：模型是发动机，Harness 是整辆车——底盘、方向盘、刹车、仪表盘。</li><li><strong>回路（Loop）</strong>：理解 → 行动 → 反馈 → 修正 的循环（第 1 章流程图）。Harness 是把回路「制度化」：每一步该看什么、该停哪、该验什么。</li><li><strong>状态（State）</strong>：任务的进度信息（第 11 章状态文件）。Harness 负责维护和传递状态，避免「失忆」。</li><li><strong>验证（Verification）</strong>：Harness 内置的检查机制（自检、验收清单、哈希校验）。注意：验证机制本身也需人工抽查（第 2、10 章教训）。</li></ul><h2 id="harness-七要素一览" tabindex="-1">Harness 七要素一览 <a class="header-anchor" href="#harness-七要素一览" aria-label="Permalink to &quot;Harness 七要素一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要素</th><th>负责什么</th><th>你已有的资产</th></tr></thead><tbody><tr><td>Agent</td><td>执行任务的主体（产品 + 模型）</td><td>第 5 章选的产品</td></tr><tr><td>上下文</td><td>给 Agent 视野</td><td>CONTEXT.md（第 11 章）</td></tr><tr><td>工具</td><td>让 Agent 动手</td><td>产品工具 + 你的 Skill（第 13 章）</td></tr><tr><td>权限</td><td>控制边界</td><td>权限分级表（第 8 章）</td></tr><tr><td>状态</td><td>记录进度</td><td>状态文件/复盘记录（第 10、11 章）</td></tr><tr><td>验证</td><td>保证质量</td><td>验收清单（第 10 章）</td></tr><tr><td>反馈</td><td>沉淀改进</td><td>规则/模板/技能迭代（第 12–14 章）</td></tr></tbody></table><h2 id="跟着做-画你的个人-harness-草图" tabindex="-1">跟着做：画你的个人 Harness 草图 <a class="header-anchor" href="#跟着做-画你的个人-harness-草图" aria-label="Permalink to &quot;跟着做：画你的个人 Harness 草图&quot;">​</a></h2><h3 id="第一步-画七个盒子" tabindex="-1">第一步：画七个盒子 <a class="header-anchor" href="#第一步-画七个盒子" aria-label="Permalink to &quot;第一步：画七个盒子&quot;">​</a></h3><p>在白纸上按「流程」排列七要素：上下文 → Agent → 工具 →（动作）→ 验证 →（输出）→ 反馈 → 状态。权限盒子横跨在「Agent 的工具使用」上方（表示门禁）。用箭头画出信息流。</p><h3 id="第二步-在每个盒子里写「我现在用什么」" tabindex="-1">第二步：在每个盒子里写「我现在用什么」 <a class="header-anchor" href="#第二步-在每个盒子里写「我现在用什么」" aria-label="Permalink to &quot;第二步：在每个盒子里写「我现在用什么」&quot;">​</a></h3><ul><li>上下文：CONTEXT.md？</li><li>Agent：哪款产品（第 6 章选的）？</li><li>工具：有哪些 Skill？</li><li>权限：用哪级？谁确认？</li><li>状态：状态文件在哪？</li><li>验证：验收清单有几项？</li><li>反馈：复盘记录更新了吗？</li></ul><h3 id="第三步-找出「空盒子」" tabindex="-1">第三步：找出「空盒子」 <a class="header-anchor" href="#第三步-找出「空盒子」" aria-label="Permalink to &quot;第三步：找出「空盒子」&quot;">​</a></h3><p>哪个盒子你还没有对应资产？比如「验证」只有模糊感觉没有清单——那就是下一章的改进点。</p><h3 id="第四步-标注「人工检查点」" tabindex="-1">第四步：标注「人工检查点」 <a class="header-anchor" href="#第四步-标注「人工检查点」" aria-label="Permalink to &quot;第四步：标注「人工检查点」&quot;">​</a></h3><p>在图里标出你必须在场的节点（高风险动作、最终发布、验收打勾）。<strong>Harness 不是「全自动机器」，是「人机协同的流水线」。</strong></p><h2 id="一个完整示例-第-5-章实测的-harness-观察" tabindex="-1">一个完整示例（第 5 章实测的 Harness 观察） <a class="header-anchor" href="#一个完整示例-第-5-章实测的-harness-观察" aria-label="Permalink to &quot;一个完整示例（第 5 章实测的 Harness 观察）&quot;">​</a></h2><p>统一基准任务的 Harness 运行观察（各产品表现见第 6 章选择表）：</p><ul><li><strong>上下文</strong>：7 份材料 + 统一任务卡 → 决定了「输入范围」；</li><li><strong>权限</strong>：多数产品无弹窗执行；Qoder/Hermes 越权读取——<strong>权限环节是它们的短板</strong>；</li><li><strong>状态</strong>：有的产品把「测试已完成」当成未完成（上下文不足导致）——状态传递失败；</li><li><strong>验证</strong>：自检质量差异巨大——Codex 覆盖 7 份输入，Qoder 称「全部通过」却漏报越界；</li><li><strong>反馈</strong>：验收记录（run-record）成为第 6 章评分的证据——反馈闭环生效。</li></ul><p><strong>结论：同一个任务，Harness 强弱决定了「能否一次通过」和「边界是否守得住」。模型几乎一样，结果差异巨大。</strong></p><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>换了个更强的模型，问题依旧</td><td>问题在 Harness 不在模型</td><td>检查七要素，先补验证/权限短板</td></tr><tr><td>Harness 画得越复杂越安心</td><td>误解了「系统化」</td><td>最小可用：先保证闭环，再谈复杂</td></tr><tr><td>全自动化，出事才后悔</td><td>没标人工检查点</td><td>高风险节点必须有「人在场」标记</td></tr><tr><td>状态没人维护，任务反复丢进度</td><td>状态盒子空了</td><td>用 CONTEXT.md + 状态文件补上</td></tr><tr><td>以为 Harness 是「买来的产品」</td><td>误解</td><td>Harness 是你自己组装的系统，产品只是 Agent 要素之一</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>Harness 草图里标注的权限边界、人工检查点，要能落到第 8 章权限卡的「允许/禁止」清单；</li><li>不要为了「自动化」省略验证——验证被自动化跳过，错误就会被放大（第 14 章杠杆）；</li><li>Harness 中任何「自动执行外部动作」的设计，都必须保留人工最终确认。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>30 分钟：按「跟着做」画你的个人 Harness 草图（七要素 + 现有资产 + 空盒子 + 人工检查点），标出 1 个最需要补强的要素。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>个人 Harness 草图</strong>（七要素、信息流、现有资产、空盒子、人工检查点）。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>Harness 是围绕模型的工作系统，决定可靠性、成本与体验；</li><li>七要素：Agent、上下文、工具、权限、状态、验证、反馈；</li><li>同一个模型在不同 Harness 里表现不同（实测证据）；</li><li>你已经拥有 Harness 的零件，本章把它们显影成图；</li><li>下一章讲 Harness 的架构设计（第 16 章）。</li></ol>',36)])])}const b=a(n,[["render",l]]);export{c as __pageData,b as default};
